"""Run OpenFOAM 12 via a Windows command wrapper cases generated by cfd_gen, serially per case, many cases concurrently.

Usage from Python:  run_spec(name, spec)  or  run_many([(name, spec), ...], workers=10)
"""
import os, sys, json, time, subprocess
from concurrent.futures import ThreadPoolExecutor, as_completed

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, '..'))
OF = os.environ.get('HIMCM_OF', os.path.abspath(os.path.join(ROOT, '..', 'tools', 'of.cmd')))
CFD = os.path.join(ROOT, 'cfd')
sys.path.insert(0, HERE)
import cfd_gen


def sh(case, *cmd, log=None, timeout=None):
    t = time.time()
    if log:   # stream to the log file so that running cases can be monitored
        with open(os.path.join(case, log), 'w') as f:
            r = subprocess.run(['cmd', '/c', OF, *cmd], cwd=case, stdout=f, stderr=subprocess.STDOUT, text=True, timeout=timeout)
    else:
        r = subprocess.run(['cmd', '/c', OF, *cmd], cwd=case, capture_output=True, text=True, timeout=timeout)
    return r.returncode, time.time() - t


def run_spec(name, spec, meta=None, sub='', skip_done=True):
    case = os.path.join(CFD, sub, name)
    done = os.path.join(case, 'done.json')
    if skip_done and os.path.exists(done):
        return json.load(open(done))
    info = cfd_gen.make(case, spec)
    json.dump(dict(meta=meta or {}, patches=info['patches'], blocks=info['blocks']), open(os.path.join(case, 'case_info.json'), 'w'))
    out = dict(name=name, ok=False)
    rc, t = sh(case, 'blockMesh', log='log.blockMesh'); out['blockMesh'] = [rc, round(t)]
    if rc:
        return out
    rc, t = sh(case, 'checkMesh', log='log.checkMesh'); out['checkMesh'] = rc
    rc, t = sh(case, 'foamRun', log='log.foamRun'); out['foamRun'] = [rc, round(t)]
    out['ok'] = rc == 0
    if out['ok']:
        json.dump(out, open(done, 'w'))
    return out


def run_many(jobs, workers=10, sub=''):
    res = []
    with ThreadPoolExecutor(max_workers=workers) as ex:
        futs = {ex.submit(run_spec, n, s, m, sub): n for n, s, m in jobs}
        for f in as_completed(futs):
            r = f.result(); res.append(r)
            print(time.strftime('%H:%M:%S'), r.get('name'), 'ok' if r.get('ok') else 'FAIL', r.get('foamRun'), flush=True)
    return res
